package com.whaa.shop.customerService.controller;import com.whaa.shop.common.api.ApiResponse;import com.whaa.shop.common.security.CurrentUser;import com.whaa.shop.customerService.application.KnowledgeService;import com.whaa.shop.customerService.domain.KnowledgeFile;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.util.List;
@RestController @RequestMapping("/api/v1/admin/knowledge") public class KnowledgeAdminController {private final KnowledgeService service;public KnowledgeAdminController(KnowledgeService s){service=s;}@GetMapping ApiResponse<List<KnowledgeFile>> list(){return ApiResponse.ok(service.list());}@PostMapping ApiResponse<KnowledgeFile> upload(@RequestParam MultipartFile file){return ApiResponse.ok(service.upload(file,CurrentUser.id()));}@PostMapping("/{id}/reindex")ApiResponse<Void> reindex(@PathVariable Long id){service.reindex(id);return ApiResponse.ok();}@DeleteMapping("/{id}")ApiResponse<Void> delete(@PathVariable Long id){service.delete(id);return ApiResponse.ok();}}
